    var NAME={1:"developer",2:"trader",3:"miser"};
    var BLURB={1:"improves and holds",2:"flips fast, deals often",3:"hoards, wants a premium"};
    window.KV_PROFNAME=function(seat){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      return NAME[Math.round(f["cur_p"+seat]||0)]||"";
    };
    var last={};
    setInterval(function(){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      var humans=window.KV_HUMANS||[1];
      for(var p=2;p<=4;p++){
        if(humans.indexOf(p)>=0) continue;
        var cur=Math.round(f["cur_p"+p]||0);
        if(!cur) continue;
        var c=document.getElementById("kvc"+p);
        var tag=document.getElementById("kvchar"+p);
        if(!tag && c && c.parentNode){
          tag=document.createElement("div");
          tag.id="kvchar"+p;
          tag.style.cssText="font-size:9px;letter-spacing:1px;margin-top:2px;";
          c.parentNode.appendChild(tag);
        }
        if(tag){
          tag.style.color=COL[p];
          tag.textContent=NAME[cur].toUpperCase()+" \u00b7 "+BLURB[cur];
        }
        if(last[p]!==undefined && last[p]!==cur){
          window.KV_LOG("P"+p+"  turns "+NAME[cur]+"  \u2014 "+BLURB[cur], COL[p]);
          if(window.KV_DEAL) window.KV_DEAL(true,"P"+p+" SHIFTS", NAME[cur].toUpperCase()+" \u00b7 "+BLURB[cur]);
        }
        last[p]=cur;
      }
    }, 900);
  })();

  // __KV_V185: in a relay game the first-roll is derived from the revealed seed so every
  // board computes the same throw; nobody's local dice decide the turn order.
  window.KV_FIRSTROLL = function(seat, round){
    var seed = (window.KV_MP2 && window.KV_MP2.seed) || window.KV_SEED || "kv";
    var str = seed + ":first:" + seat + ":" + (round||0), h = 2166136261;
    for (var i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
    var a = ((h>>>0) % 6) + 1, b = (((h>>>8)>>>0) % 6) + 1;
    return [a, b, a+b];
  };

  // ---- roll for first (v107) ----
(function(){
  var COL={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};
  // __KV_V186: read live — the DAA gun sets KV_HUMANS after this block is parsed
  function humansNow(){ return window.KV_HUMANS||[1]; }
  var humans={ indexOf:function(x){ return humansNow().indexOf(x); } };
  var ov=document.createElement("div");
  ov.style.cssText="position:fixed;inset:0;z-index:90;background:rgba(10,8,6,.18);display:flex;align-items:center;justify-content:center;"; ov.setAttribute("data-kvmodal","1");
  var box=document.createElement("div");
  box.style.cssText="background:#14100c;border:2px solid #caa64c;border-radius:12px;padding:20px 28px;min-width:380px;font:13px/1.8 monospace;color:#f4e4c1;text-align:center;";
  ov.appendChild(box); document.body.appendChild(ov);
  ["pointerdown","pointerup","keydown","click"].forEach(function(t){ ov.addEventListener(t,function(e){ e.stopPropagation(); }); });
  var rolls={}, pool=[1,2,3,4], round=0;
  // __KV_V186: relay games derive every throw from the revealed seed
  function relay(){ return !!(window.KV_MP2 && window.KV_MP2.room && window.KV_MP2.started && window.KV_MP2.seed); }   // __KV_V200
  function throwFor(seat){
    if(relay()){ var r=window.KV_FIRSTROLL(seat, round); return [r[0], r[1]]; }
    return [1+Math.floor(Math.random()*6), 1+Math.floor(Math.random()*6)];
  }
  function d6(){ return 1+Math.floor(Math.random()*6); }
  function render(msg){
    var h="<div style='font:900 26px Impact,sans-serif;color:#f0c860;letter-spacing:2px;margin-bottom:8px'>ROLL FOR FIRST</div>";
    [1,2,3,4].forEach(function(s){
      var r=rolls[s];
      h+="<div><span style='color:"+COL[s]+";font-weight:700'>P"+s+(humans.indexOf(s)>=0?" (you)":"")+"</span> &nbsp; "+(r?("<b>"+r[0]+" + "+r[1]+" = "+(r[0]+r[1])+"</b>"):"<span style='opacity:.4'>—</span>")+(pool.indexOf(s)<0?" <span style='opacity:.4'>out</span>":"")+"</div>";
    });
    h+="<div style='margin-top:10px;color:#caa64c'>"+msg+"</div>";
    box.innerHTML=h;
  }
  function next(){
    // __KV_V187: in a relay game nothing is thrown until the shared start has landed —
    // the seed arrives with the gun, and every board must throw from that same seed
    if(window.KV_MP2 && window.KV_MP2.room && (!window.KV_MP2.started || !window.KV_MP2.seed)){   // __KV_V200: seed too
      render("waiting for all players — the throw is shared");
      setTimeout(next, 700);
      return;
    }
    var pending=pool.filter(function(s){ return !rolls[s]; });
    if(pending.length){
      var s=pending[0];
      if(!relay() && humans.indexOf(s)>=0){
        render("your roll — tap to throw");
        var b=document.createElement("button");
        b.style.cssText="margin-top:10px;padding:9px 26px;background:#2f4a2f;color:#cfe6c4;border:1px solid #4fd98a;border-radius:6px;font:900 14px monospace;cursor:pointer;";
        b.textContent="ROLL"; box.appendChild(b);
        b.onclick=function(e){ e.stopPropagation(); rolls[s]=throwFor(s); if(window.KV_MOVE) window.KV_MOVE(s,"first",rolls[s][0]+rolls[s][1]); next(); };
      } else {
        // __KV_V201: the guest does not throw — it takes the host's value from the relay
        if(relay() && !window.KV_MP2.owns(s)){   // __KV_V202: not my seat -> its owner throws, I read
          var __L=(window.KV_MP2.firstList||{})[s]||[], __v=__L[round];
          if(__v==null){ render("P"+s+" — waiting for the host's throw…"); setTimeout(next, 500); return; }
          render("P"+s+" — from the host…");
          setTimeout(function(){ var a=Math.max(1,Math.min(6,Math.ceil(__v/2))), b=Math.max(1,Math.min(6,__v-a)); rolls[s]=[a,b]; if(window.KV_MOVE) window.KV_MOVE(s,"first",__v); next(); }, 250);
          return;
        }
        render(relay() ? ("P"+s+" — shared throw…") : ("P"+s+" rolling…"));
        setTimeout(function(){ rolls[s]=throwFor(s); if(window.KV_MOVE) window.KV_MOVE(s,"first",rolls[s][0]+rolls[s][1]); next(); }, relay()?350:550);
      }
      return;
    }
    var best=-1; pool.forEach(function(s){ best=Math.max(best, rolls[s][0]+rolls[s][1]); });
    var top=pool.filter(function(s){ return rolls[s][0]+rolls[s][1]===best; });
    if(top.length>1 && round<6){
      round++; pool=top; top.forEach(function(s){ delete rolls[s]; });
      render("tie at "+best+" — "+top.map(function(s){return "P"+s;}).join(", ")+" roll again");
      setTimeout(next, 900); return;
    }
    var w=top[0];
    render("<b style='color:"+COL[w]+"'>P"+w+(humans.indexOf(w)>=0?" (you)":"")+"</b> goes first");
    if(window.KV_SETSTATE){ window.KV_SETSTATE("turn", w-1); window.KV_SETSTATE("seat", w); } window.KV_SETSTATE("seat", w);
    if(window.KV_LOG) window.KV_LOG("P"+w+" rolled "+best+" — goes first", COL[w]);
    setTimeout(function(){
      ov.remove();
      var tries=0, applied=false;
      var iv=setInterval(function(){
        var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
        if(!(f.t0>0)){
          if(tries++<20){ var c=document.querySelector("canvas"); if(c){ var r=c.getBoundingClientRect(); var o={bubbles:true,cancelable:true,clientX:r.left+3,clientY:r.top+3,pointerId:1,pointerType:"mouse",isPrimary:true,button:0};
            try{ c.dispatchEvent(new PointerEvent("pointerdown",o)); }catch(e){} document.dispatchEvent(new Event("pointerdown")); } }
          return;
        }
        if(!applied){ applied=true; if(window.KV_SETSTATE){ window.KV_SETSTATE("turn", w-1); window.KV_SETSTATE("seat", w); window.KV_SETSTATE("phase",0); window.KV_SETSTATE("moved",0); window.KV_SETSTATE("asked",0); window.KV_SETSTATE("go",-1); if(window.KV_CLEAR_DICE) window.KV_CLEAR_DICE(); window.KV_SETSTATE("buy",-1); window.KV_SETSTATE("buy_tile",-1); window.KV_SETSTATE("offer_ask",-1); } }
        var seatNow=f.seat||(((f.turn||0)%4)+1);
        var rolled=(window.KV_MOVES||[]).some(function(m){ return m.a==="roll"; }); if(rolled || tries++>26){ clearInterval(iv); if(window.KV_LOG) window.KV_LOG("P"+w+" opens the game","#caa64c"); }
        else if(window.KV_SETSTATE && seatNow!==w){ window.KV_SETSTATE("turn", w-1); window.KV_SETSTATE("seat", w); window.KV_SETSTATE("phase",0); window.KV_SETSTATE("moved",0); window.KV_SETSTATE("asked",0); window.KV_SETSTATE("go",-1); if(window.KV_CLEAR_DICE) window.KV_CLEAR_DICE(); window.KV_SETSTATE("buy",-1); window.KV_SETSTATE("buy_tile",-1); }
      }, 300);
    }, 1400);
  }
  render("who goes first?");
  setTimeout(next, 800);
})();

// ---- per-seat turn counter in the feed header (v107) ----
setInterval(function(){
  var heads=document.querySelectorAll("div"); var head=null;
  for(var i=0;i<heads.length;i++){ if(heads[i].textContent.indexOf("WHAT HAD HAPPENED WAS")===0 && heads[i].children.length<2){ head=heads[i]; break; } }
  if(!head) return;
  var c={1:0,2:0,3:0,4:0}; (window.KV_MOVES||[]).forEach(function(m){ if(m.a==="roll") c[m.s]++; });
  var COL={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};
  head.innerHTML="WHAT HAD HAPPENED WAS <span style='float:right;letter-spacing:0;font-weight:600'>turns "+[1,2,3,4].map(function(s){ return "<span style='color:"+COL[s]+"'>P"+s+" "+c[s]+"</span>"; }).join(" · ")+"</span>";
}, 1000);

// ---- bot phase-21 loop breaker (v120) ----
(function(){
  var since=null, lastTurn=null;
  setInterval(function(){
    var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
    if(f.over || window.KV_SEALED || !(f.t0>0)) return;
    if(window.KV_MP2 && window.KV_MP2.room) return;     // __KV_V189: relay games are driven by the record
    var seat=((f.turn||0)%4)+1;
    var bot=(window.KV_HUMANS||[1]).indexOf(seat)<0;
    if(!(bot && f.phase===21)){ since=null; return; }
    if(since===null || lastTurn!==f.turn){ since=Date.now(); lastTurn=f.turn; return; }
    if(Date.now()-since<1500) return;
    since=null;
    if(!window.KV_SETSTATE) return;
    window.KV_SETSTATE("offer_ask",-1); window.KV_SETSTATE("oq",0); window.KV_SETSTATE("mkoffer",-1);
    // __KV_V291: in a relay game the chain advances turns, not this timer
    if(window.KV_MP2 && window.KV_MP2.room && window.KV_MP2.started){
      if(window.KV_LOG) window.KV_LOG("P"+seat+" ends turn (chain advances)","#7a6a58");
      return;
    }
    window.KV_SETSTATE("turn",(f.turn||0)+1); window.KV_SETSTATE("seat",(((f.turn||0)+1)%4)+1); window.KV_SETSTATE("phase",0); window.KV_SETSTATE("moved",0); window.KV_SETSTATE("asked",0);
    if(window.KV_LOG) window.KV_LOG("P"+seat+" ends turn","#7a6a58");
  }, 500);
})();

// ---- holding period (v135) ----
(function(){
  var HOLD=7, lastOwner={}, boughtAt={}, prevOwner={}, NOBACK=30;   // __KV_V344: 7 turns
  window.KV_NO_BACK=function(t,buyer){ var f=(window.KV_FLAGS&&window.KV_FLAGS())||{}; return !!(prevOwner[t] && prevOwner[t].who===buyer && (f.turn||0)-prevOwner[t].at<NOBACK); };
  window.KV_HOLD_LEFT=function(t){ var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
    if(boughtAt[t]==null) return 0;
    if((f["rv_t"+t]||0)>=3) return 0;                              // __KV_V344: fully renovated lists now
    return Math.max(0, HOLD-((f.turn||0)-boughtAt[t])); };
  setInterval(function(){
    var f=(window.KV_FLAGS&&window.KV_FLAGS())||{}; if(!(f.t0>0)) return;
    var N=window.KV_NAMES||{};
    Object.keys(N).forEach(function(k){ var t=parseInt(k,10); var o=window.KV_OWNER?window.KV_OWNER(t):null;
      if(lastOwner[t]===undefined){ lastOwner[t]=o; return; }
      if(o!==lastOwner[t]){ if(lastOwner[t]) prevOwner[t]={who:lastOwner[t],at:(f.turn||0)}; lastOwner[t]=o; if(o) boughtAt[t]=(f.turn||0); }
      if(o && f["ls_t"+t]>0 && window.KV_HOLD_LEFT(t)>0 && window.KV_SETSTATE){
        window.KV_SETSTATE("ls_t"+t,0);
        if(window.KV_LOG) window.KV_LOG("P"+o+" can't relist "+(N[k].n||t)+" yet \u2014 "+window.KV_HOLD_LEFT(t)+" turns to hold","#7a6a58");
      }
    });
  }, 400);
})();

// ---- seat-change reset (v137) ----
(function(){ var lastSeat=null; setInterval(function(){ var f=(window.KV_FLAGS&&window.KV_FLAGS())||{}; if(!(f.t0>0)||f.over) return; var s=f.seat||1; if(lastSeat===null){ lastSeat=s; return; } if(s!==lastSeat){ lastSeat=s; if(window.KV_SETSTATE && !(f.moved>0)){ window.KV_SETSTATE("asked",0); window.KV_SETSTATE("go",-1); if(window.KV_CLEAR_DICE) window.KV_CLEAR_DICE(); } } },200); })();

// ---- human cash ledger (v140, diagnostic) ----
(function(){
  var last={}, lastSnd="", lastSndT=0, bleed={}; var prev=window.KV_ON_SOUND;
  window.KV_ON_SOUND=function(id){ try{ if(prev) prev(id); }catch(e){} lastSnd=id; lastSndT=Date.now(); };
  function cash(p){ var v=null; try{ v=(window.KV_SEAT&&window.KV_SEAT(p,"cash")); }catch(e){} if(v==null){ v=((window.KV_FLAGS&&window.KV_FLAGS())||{})["cash"+p]; } return v==null?null:Math.round(v); }
  setInterval(function(){
    var f=(window.KV_FLAGS&&window.KV_FLAGS())||{}; if(!(f.t0>0)||window.KV_SEALED) return;
    (window.KV_HUMANS||[1]).forEach(function(p){ var c=cash(p); if(c==null) return; if(last[p]==null){ last[p]=c; return; } if(c!==last[p]){ var d=c-last[p]; last[p]=c;
      var tag=(Date.now()-lastSndT<1500?lastSnd:"-")+"|ph"+f.phase+"|s"+(f.seat||"?")+"|tr"+f.tr_state+"|sc"+f.sc_state;
      if(window.KV_LOG) window.KV_LOG("P"+p+" cash "+(d>0?"+":"")+d+" \u2192 "+c+"  ["+tag+"]", d<0?"#ff9a7a":"#9cd87c");
      if(d<0){ var k=p+"|"+tag.split("|")[0]; var e=bleed[k]=bleed[k]||{n:0,sum:0,t:Date.now(),warned:0};
        if(Date.now()-e.t>40000){ e.n=0; e.sum=0; }
        e.n++; e.sum+=d; e.t=Date.now();
        if(e.n>=3 && Date.now()-e.warned>20000){ e.warned=Date.now();
          if(window.KV_SHOUT) window.KV_SHOUT("YOU'RE BLEEDING", "P"+p+" down "+(-e.sum)+" and counting \u2014 resolve your card", "#ff4a3a", true);
          if(window.KV_LOG) window.KV_LOG("P"+p+" recurring charge "+(-e.sum)+" total \u2014 an open card is draining you","#ff4a3a");
        } } } });
  },150);
})();

// ---- holding cell marker (v163) ----
(function(){
  setInterval(function(){
    try {
      var lab = document.querySelectorAll("div");
      for (var i = 0; i < lab.length; i++) {
        var d = lab[i];
        if (d.__kvHold) continue;
        if (d.textContent === "tile 10" || d.textContent === "Block 10") {
          d.__kvHold = 1; d.textContent = "HOLDING CELL";
          d.style.color = "#ff6a4a"; d.style.textShadow = "1px 1px 0 #241c12, 0 0 8px #ff4a3a";
        }
      }
    } catch (e) {}
  }, 1500);
})();

// ---- __KV_V262: timestamp snapshot adopts (movement trace ignores teleports) ----
(function(){ var iv=setInterval(function(){
  if(!window.KV_ADOPT || window.KV_ADOPT.__kvWrapped) return;
  var orig=window.KV_ADOPT;
  var w=function(sn){ window.__KV_ADOPT_AT=Date.now(); return orig(sn); };
  w.__kvWrapped=1; window.KV_ADOPT=w; clearInterval(iv);
}, 500); })();

// ---- movement trace (v162) ----
(function(){
  var last = {}, lastDice = {};
  function nm(t){ var N = window.KV_NAMES || {}; return (N[t] && N[t].n) || ("tile " + t); }
  setInterval(function(){
    var f = (window.KV_FLAGS && window.KV_FLAGS()) || {};
    if (!(f.t0 > 0) || window.KV_SEALED) return;
    var __relay = !!(window.KV_MP2 && window.KV_MP2.room && window.KV_MP2.started);   // __KV_V261: judge only owned seats in a relay game   // __KV_V250: the chain judges movement in a relay game
    var dice = (f.d1 || 0) + (f.d2 || 0);
    for (var p = 1; p <= 4; p++) {
      var cur = f["p" + p];
      if (cur == null) continue;
      if (last[p] == null) { last[p] = cur; continue; }
      if (cur === last[p]) continue;
      var from = last[p], to = cur; last[p] = cur;
      if (__relay) { var __mp2=window.KV_MP2; if(!(p===__mp2.seat || (__mp2.owns&&__mp2.owns(p)))) continue; }
      if (__relay) { continue; }   // __KV_V307: in a relay game the chain places every token
      var expect = ((from + dice) % 40 + 40) % 40;
      var fwd = ((to - from) % 40 + 40) % 40;
      var wrap = (to < from) ? " WRAP" : "";
      var holding = (to === 10 && to !== expect);
      var okm = (to === expect) ? "ok" : (holding ? "HOLDING" : "MISMATCH");
      if (holding) {
        var CRIMES = ["permits forged", "inspector bribed", "books cooked", "tenants shut out illegally",
                      "safety notices ignored", "rent skimmed off the books", "deeds falsified",
                      "site worked without licence", "meter tampered with", "cash paid under the table"];
        var crime = CRIMES[((f.turn || 0) + p) % CRIMES.length];
        if (window.KV_SHOUT) window.KV_SHOUT("CAUGHT \u2014 SENT TO HOLDING",
          "P" + p + " \u00b7 " + crime + " \u00b7 fined 50 \u00b7 turn ends", "#ff4a3a",
          (window.KV_HUMANS || [1]).indexOf(p) >= 0);
        if (window.KV_LOG) window.KV_LOG("P" + p + " caught: " + crime + " \u2014 sent to the Holding Cell, fined 50", "#ff4a3a");
        if (__relay && window.KV_MOVE) window.KV_MOVE(p, "court", 50);   // __KV_V261: tell the chain
      }
      var line = "M:P" + p + " " + from + "->" + to + " dice=" + dice + " expect=" + expect +
                 " step=" + fwd + " " + okm + wrap;
      if (!__relay && to !== expect && window.KV_MOVE) window.KV_MOVE(0, line.slice(0, 70), to);
      if (to !== expect && window.KV_LOG) window.KV_LOG(line + "  (" + nm(from) + " -> " + nm(to) + ")",
                                       (to === expect) ? "#8ab4d8" : "#ff4a3a");
      if (!__relay && to !== expect && !holding && window.KV_SHOUT) {
        window.KV_SHOUT("MOVE MISMATCH", "P" + p + " " + from + "->" + to + " but dice " + dice +
                        " means " + expect, "#ff4a3a", (window.KV_HUMANS || [1]).indexOf(p) >= 0);
      }
    }
  }, 120);
})();

// ---- stall detector (escalating) ----
  (function(){
    var lastKey=null, since=Date.now(), step=0;
    setInterval(function(){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      if(f.over || window.KV_SEALED) return;
      // watch the turn AND the move count AND the clock: a stall can freeze any one of them
      if(window.KV_MP2 && window.KV_MP2.room) return;   // __KV_V189: no local nudging in a relay game
      if(!(f.t0>0)){ since=Date.now(); step=0; return; }  // v103: not started yet = not a stall
if(window.KV_SCN_BUSY && window.KV_SCN_BUSY()){ since=Date.now(); step=0; return; }
var __hum=(window.KV_HUMANS||[1]).indexOf(((f.turn||0)%4)+1)>=0;
if(__hum){
  var __dlg=!!document.querySelector("[data-kvmodal]");
  if(__dlg){ since=Date.now(); step=0; return; }
  if((Date.now()-since)/1000 < 30) return;
}  // v102: card open = not a stall
var key=[f.turn, (window.KV_MOVES||[]).length, f.phase, f.asked].join("/");
      if(key!==lastKey){ lastKey=key; since=Date.now(); step=0; return; }
      var stuck=(Date.now()-since)/1000;
      if(stuck>6 && step===0){
        step=1;
        if(window.KV_SETSTATE){
          window.KV_SETSTATE("renov",-1); window.KV_SETSTATE("renov_by",0);
          window.KV_SETSTATE("sc_state",0);
          window.KV_SETSTATE("sc_sell",-1); window.KV_SETSTATE("offer_ask",-1);
        }
      } else if(stuck>10 && step===1){
        step=2;
        if(window.KV_SETSTATE){ window.KV_SETSTATE("asked",0); window.KV_SETSTATE("phase",(f.moved>0)?3:0); }
        if(window.KV_LOG) window.KV_LOG("turn stalled "+Math.round(stuck)+"s — nudging","#e08a5a");
      } else if(stuck>16 && step===2){
        step=3;
        // last resort: hand the turn to the next seat
        var seat=((f.turn||0)%4)+1;
        if(window.KV_SETSTATE){
          if(window.KV_MP2 && window.KV_MP2.room && window.KV_MP2.started){ step=3; return; }   // __KV_V291
          window.KV_SETSTATE("turn",(f.turn||0)+1); window.KV_SETSTATE("seat",(((f.turn||0)+1)%4)+1);
          window.KV_SETSTATE("phase",0);
          window.KV_SETSTATE("moved",0);
          window.KV_SETSTATE("asked",0);
        }
        if(window.KV_LOG) window.KV_LOG("P"+seat+" was stuck — turn passed on","#ff6a4a");
      }
    }, 1200);
  })();

  // ================= DEAL BANNER =================
  (function(){
    var bn=document.createElement("div");
    bn.style.cssText="position:fixed;left:50%;top:44%;transform:translate(-50%,-50%) scale(.9);z-index:74;display:none;padding:14px 34px;border-radius:12px;text-align:center;font:900 30px Impact,'Arial Black',sans-serif;letter-spacing:3px;color:#12100e;box-shadow:0 10px 40px rgba(0,0,0,.75);transition:transform .18s,opacity .18s;opacity:0;";
    document.body.appendChild(bn);
    var hideT=null;
    window.KV_DEAL=function(ok, headline, detail){
