// ---- per-move state commitments (v170) ----
(function(){
  var chain = "";           // running commitment
  var history = [];         // {index, seat, action, value, hash}
  var halted = false;

  async function sha(s){
    try{
      var b = new TextEncoder().encode(s);
      var d = await crypto.subtle.digest("SHA-256", b);
      return Array.from(new Uint8Array(d)).map(function(x){ return x.toString(16).padStart(2,"0"); }).join("");
    }catch(e){
      var h = 0; for (var i=0;i<s.length;i++){ h = ((h<<5)-h+s.charCodeAt(i))|0; }
      return ("00000000"+(h>>>0).toString(16)).slice(-8).repeat(8);
    }
  }

  // the canonical state string: everything a rules engine determines, nothing cosmetic
  function snapshot(){
    var w = window.KV_WORLD, f = (window.KV_FLAGS && window.KV_FLAGS()) || {};
    var cash = [], pos = [], own = [];
    for (var p = 1; p <= 4; p++) {
      var c = 0; try { c = Math.round((w && w.seats && w.seats[p-1] && w.seats[p-1].cash) || 0); } catch(e){}
      cash.push(c);
      pos.push(f["p"+p] == null ? -1 : f["p"+p]);
    }
    try {
      var keys = Object.keys((w && w.owners) || {}).sort();
      keys.forEach(function(k){ if (w.owners[k]) own.push(k + ">" + w.owners[k]); });
    } catch(e){}
    var xp=[]; for(var q=1;q<=4;q++){ xp.push(Math.round((window.KV_XP&&window.KV_XP[q])||0)); }   // __KV_V266
    return cash.join(",") + "|" + pos.join(",") + "|" + own.join(",") + "|" + xp.join(",");
  }

  async function commitMove(index, seat, action, value, __snap){   // __KV_V210
    var body = [chain, index, seat, action, value, (__snap != null ? __snap : snapshot())].join("~");
    chain = await sha(body);
    history.push({ index: index, seat: seat, action: action, value: value, hash: chain });
    if (history.length > 400) history.shift();
    return chain;
  }

  window.KV_SNAPSHOT = snapshot;   // __KV_V210
  // __KV_V267: adopted positions walk, not teleport
  window.__KV_WALK = window.__KV_WALK || {};
  function __kvWalkTo(p, target){
    try{
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{}; var cur=f["p"+p];
      if(window.__KV_WALK[p]){ clearInterval(window.__KV_WALK[p]); delete window.__KV_WALK[p]; }
      if(cur==null || cur<0 || cur===target){ window.KV_SETSTATE("p"+p, target); return; }
      var steps=((target-cur)%40+40)%40;
      if(steps===0 || steps>12){ window.KV_SETSTATE("p"+p, target); return; }
      var at=cur;
      window.__KV_WALK[p]=setInterval(function(){
        at=(at+1)%40; window.KV_SETSTATE("p"+p, at);
        if(at===target){ clearInterval(window.__KV_WALK[p]); delete window.__KV_WALK[p]; }
      }, 120);
    }catch(e){ try{ window.KV_SETSTATE("p"+p, target); }catch(e2){} }
  }
  // __KV_V212: symmetric writer — apply a snapshot as the board's new state
  window.KV_ADOPT = function(snap){
    window.__KV_NO_LAP = Date.now();                             // __KV_V356: an adopt walk is a replay, not travel
    try{
      var parts=String(snap||"").split("|");
      var w=window.KV_WORLD;
      var cash=(parts[0]||"").split(",").map(Number);
      var pos=(parts[1]||"").split(",").map(Number);
      for(var p=1;p<=4;p++){
        if(w && w.seats && w.seats[p-1] && isFinite(cash[p-1])) w.seats[p-1].cash = cash[p-1];
        if(window.KV_SETSTATE && isFinite(cash[p-1])) window.KV_SETSTATE("cash"+p, cash[p-1]);
        if(window.KV_SETSTATE && isFinite(pos[p-1]) && pos[p-1]>=0) __kvWalkTo(p, pos[p-1]);   // __KV_V267
      }
      if(w && parts[2]!=null){                                     // __KV_V349: hydrate even when owners was never initialized
        w.owners = w.owners || {};
        var incoming={};
        (parts[2]?parts[2].split(","):[]).forEach(function(e){ var kv=e.split(">"); if(kv[0]) incoming[kv[0]]=parseInt(kv[1],10)||0; });
        Object.keys(w.owners).forEach(function(k){ if(!incoming[k]) delete w.owners[k]; });
        Object.keys(incoming).forEach(function(k){ w.owners[k]=incoming[k]; });
      }
      // __KV_V266: xp travels with the snapshot
      if(parts[3]!=null && window.KV_XP){
        var xpA=(parts[3]||"").split(",").map(Number);
        for(var q2=1;q2<=4;q2++){ if(isFinite(xpA[q2-1])) window.KV_XP[q2]=xpA[q2-1]; }
      }
      return true;
    }catch(e){ return false; }
  };
  window.KV_COMMIT = {
    head: function(){ return chain; },
    snapshot: snapshot,
    add: commitMove,
    history: function(){ return history.slice(-12); },
    halted: function(){ return halted; },
    // verify a peer move: recompute from our own state and compare
    check: async function(m){
      if (halted || !m || m.hash == null) return true;
      var mine = await commitMove(m.index, m.seat, m.action, m.value || 0, m.snap);   // __KV_V213: verify what the mover actually hashed
      if (mine === m.hash) return true;
      // __KV_V213: update model — adopt, warn, never halt mid-game
      if (window.KV_ADOPT && m.snap){ window.KV_ADOPT(m.snap); }
      if (window.KV_LOG) window.KV_LOG("hash mismatch at move " + m.index + " (" + m.action + ") — adopted mover state, replay will judge", "#e0a040");
      return true;
      halted = true;
      if (window.KV_NET) window.KV_NET.diverged = true;
      if (window.KV_LOG) window.KV_LOG("STATE MISMATCH at move " + m.index + " (" + m.action + ")" +
        " \u2014 peer says " + String(m.hash).slice(0,12) + ", we compute " + String(mine).slice(0,12), "#ff4a3a");
      if (window.KV_SHOUT) window.KV_SHOUT("GAME HALTED",
        "the boards disagree at move " + m.index + " \u2014 the result will not be signed", "#ff4a3a", true);
      return false;
    }
  };

  if (window.KV) {
    window.KV.commit = function(){
      var r = { head: chain.slice(0,24), halted: halted, moves: history.length };
      console.log(r); console.table(history.slice(-8).map(function(h){
        return { i: h.index, seat: "P"+h.seat, action: h.action, value: h.value, hash: String(h.hash).slice(0,12) }; }));
      return r;
    };
    window.KV.snapshot = function(){ var s = snapshot(); console.log(s); return s; };
  }
})();

// ---- multi-node relay (v169) ----
(function(){
  var APP = "kasvillage", PORT = 35816;
  var DOMAIN = "https://kasvillage.app.runonflux.io";
  var NODES = [];            // [{base, ok, fails}]
  var lastDiscovery = 0;

  function log(m, c){ if (window.KV_LOG) window.KV_LOG(m, c || "#7a9ac9"); }

  async function probe(base){
    try{
      var c = new AbortController(); var t = setTimeout(function(){ c.abort(); }, 4000);
      var r = await KV_WNET.req(base + "/health", { signal: c.signal });
      clearTimeout(t);
      return r.ok;
    }catch(e){ return false; }
  }

  async function discover(force){
    if (!force && Date.now() - lastDiscovery < 60000 && NODES.some(function(n){ return n.ok; })) return NODES;
    lastDiscovery = Date.now();
    var found = [];
    try{
      var c = new AbortController(); var t = setTimeout(function(){ c.abort(); }, 6000);
      var r = await KV_WNET.req("https://api.runonflux.io/apps/location/" + APP, { signal: c.signal });
      clearTimeout(t);
      var j = await r.json();
      (j && j.data ? j.data : []).forEach(function(d){
        var ip = String(d.ip || "").split(":")[0];
        if (ip) found.push("http://" + ip + ":" + PORT);
      });
    }catch(e){ log("node discovery failed, using the domain only", "#e0a040"); }
    if (!found.length) found.push(DOMAIN);
    else found.push(DOMAIN);   // the load balancer is a useful extra path

    var checked = await Promise.all(found.map(async function(base){
      return { base: base, ok: await probe(base), fails: 0 };
    }));
    NODES = checked;
    var live = NODES.filter(function(n){ return n.ok; });
    log("relay nodes: " + live.length + " of " + NODES.length + " reachable", live.length ? "#9cd87c" : "#ff6a4a");
    return NODES;
  }

  function live(){ return NODES.filter(function(n){ return n.ok; }); }

  async function once(node, path, opts){
    var c = new AbortController(); var t = setTimeout(function(){ c.abort(); }, 6000);
    try{
      var r = await KV_WNET.req(node.base + path, Object.assign({ signal: c.signal,
        headers: { "Content-Type": "application/json" } }, opts || {}));
      clearTimeout(t);
      if (!r.ok) throw new Error("HTTP " + r.status);
      node.fails = 0;
      return await r.json();
    }catch(e){
      clearTimeout(t);
      node.fails = (node.fails || 0) + 1;
      if (node.fails >= 3) { node.ok = false; log("node dropped: " + node.base, "#e0a040"); }
      throw e;
    }
  }

  // write to every healthy node; resolve on the first success
  async function broadcast(path, opts){
    if (!live().length) await discover(true);
    var nodes = live(); if (!nodes.length) throw new Error("no relay reachable");
    var results = await Promise.allSettled(nodes.map(function(n){ return once(n, path, opts); }));
    var good = results.filter(function(r){ return r.status === "fulfilled"; });
    if (!good.length) { await discover(true); throw new Error("all relays failed"); }
    return good[0].value;
  }

  // read from every healthy node and merge the move lists by index
  async function gather(path){
    if (!live().length) await discover(true);
    var nodes = live(); if (!nodes.length) throw new Error("no relay reachable");
    var results = await Promise.allSettled(nodes.map(function(n){ return once(n, path, { method: "GET" }); }));
    var good = results.filter(function(r){ return r.status === "fulfilled"; }).map(function(r){ return r.value; });
    if (!good.length) { await discover(true); throw new Error("all relays failed"); }
    var byIndex = {}, players = [], ended = false, seed = null;
    good.forEach(function(res){
      (res.moves || []).forEach(function(m){ if (byIndex[m.index] == null) byIndex[m.index] = m; });
      if ((res.players || []).length > players.length) players = res.players;
      if (res.ended) ended = true;
      if (res.seed && !seed) seed = res.seed;
    });
    var moves = Object.keys(byIndex).map(Number).sort(function(a,b){ return a-b; }).map(function(i){ return byIndex[i]; });
    return { moves: moves, players: players, ended: ended, seed: seed };
  }

  window.KV_RELAY = {
    discover: discover,
    nodes: function(){ return NODES.map(function(n){ return { base: n.base, ok: n.ok, fails: n.fails || 0 }; }); },
    post: function(path, body){ return broadcast(path, { method: "POST", body: JSON.stringify(body || {}) }); },
    get: function(path){ return gather(path); }
  };

  if (window.KV) {
    window.KV.nodes = function(){ var n = window.KV_RELAY.nodes(); console.table(n); return n; };
    window.KV.rediscover = async function(){ await discover(true); return window.KV.nodes(); };
  }

  discover(true);
})();

