    if(!w){ var a=new Uint8Array(12); crypto.getRandomValues(a);
      w = "kcw"+Array.from(a).map(function(x){return x.toString(16).padStart(2,"0");}).join("");
      localStorage.setItem("kv_mp2_wallet", w); }
    M.wallet = w; return w;
